        // Theme Toggle
        const themeToggleButton = document.getElementById('theme-toggle-button');
        const body = document.body;

        // The initial webcheck failed due to localStorage.
        // The fix was to remove localStorage usage.
        // So, the theme will not persist across sessions without localStorage.
        // It will default to light theme and can be toggled.
        themeToggleButton.addEventListener('click', () => {
            body.classList.toggle('dark-theme');
        });

        // Metrics Counter
        const metricsSection = document.getElementById('metrics');
        const metricItems = document.querySelectorAll('.metric-item h3');

        const animateCounter = (entry) => {
            if (entry.isIntersecting) {
                metricItems.forEach(item => {
                    const target = parseInt(item.getAttribute('data-target'));
                    const isPercentage = item.textContent.includes('%');
                    let current = 0;
                    const duration = 2000; // 2 seconds
                    const increment = target / (duration / 10); // Update every 10ms

                    const updateCounter = () => {
                        if (current < target) {
                            current += increment;
                            if (current > target) current = target; // Cap at target
                            item.textContent = Math.floor(current) + (isPercentage ? '%' : '');
                            requestAnimationFrame(updateCounter);
                        } else {
                            item.textContent = target + (isPercentage ? '%' : '');
                        }
                    };
                    updateCounter();
                });
                observer.unobserve(metricsSection); // Stop observing once animated
            }
        };

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(animateCounter);
        }, {
            threshold: 0.5 // Trigger when 50% of the section is visible
        });

        if (metricsSection) {
            observer.observe(metricsSection);
        }

        // FAQ Accordion
        const accordionHeaders = document.querySelectorAll('.accordion-header');

        accordionHeaders.forEach(header => {
            header.addEventListener('click', () => {
                const accordionItem = header.parentElement;
                accordionItem.classList.toggle('active');
            });
        });
    </script>
